import type { RawClaim, ClaimGroup } from '../../../src/adapters/ai/multipass/contracts';
import type { SafetyCandidate, SafetyVerdict } from '../../../src/adapters/ai/multipass/safety';

type FactSpec = { messageId: string; focus: string; fieldId: string; value: RawClaim['value']; scope: 'case' | 'buying_unit' | 'participant'; unit?: string; period?: string; incomeBasis?: RawClaim['incomeBasis']; precision?: RawClaim['precision'] };
function claimsFor(snapshot: Snapshot, specs: FactSpec[]): RawClaim[] {
  return specs.map(spec => {
    const message = snapshot.messages.find(m => m.messageId === spec.messageId);
    if (!message || message.content.type !== 'text') throw new Error('text missing');
    const text = message.content.text; const start = text.indexOf(spec.focus);
    if (start < 0) throw new Error('focus missing');
    return { fieldId: spec.fieldId, subjectRef: { scope: spec.scope, id: spec.scope === 'case' ? 'case' : spec.scope === 'buying_unit' ? 'unit' : 'person' }, value: spec.value, precision: spec.precision ?? 'explicit', ...(spec.unit && { unit: spec.unit }), ...(spec.period && { period: spec.period }), ...(spec.incomeBasis && { incomeBasis: spec.incomeBasis }), occurrence: { messageId: spec.messageId, statementSpan: { start: 0, end: text.length, text }, focusSpan: { start, end: start + spec.focus.length, text: spec.focus } }, evidenceRefs: [{ messageId: spec.messageId, quote: text }] };
  });
}
function fakeCase(claims: RawClaim[], signals: SafetyCandidate[] = [], verdicts: SafetyVerdict[] = [], options: { delays?: Record<string, number>; conflict?: boolean; adjudicate?: 'valid' | 'invalid' | 'unresolved' } = {}): FakeTransport {
import { randomUUID } from 'node:crypto';
import type { Interpreter, SubjectRef } from '../../../contracts';
import { validateInterpretation, failure } from '../validation';
import { runPipeline } from './pipeline';
import type { FakeTransport } from './scheduler';
import { PROMPT_VERSION } from './prompts';
import { validateAssertions } from '../../../domain/facts';

// Versioned PoC profile: sensitive financial amounts and purchase structure
// require corroboration. Sensitivity is not used as a proxy for materiality.
export const RECONCILIATION_PROFILE = { version: 'poc-material-1', fields: ['declared_monthly_income', 'available_savings', 'monthly_debt', 'buyer_count'] } as const;
export class MultipassInterpreter implements Interpreter {
  constructor(private transport: FakeTransport) {}
  async interpret(input: Parameters<Interpreter['interpret']>[0]) {
    const historical = input.caseSnapshot.assertions;
    // Case identity is intrinsic to the case. Other identities only come from
    // existing, non-rejected case assertions; no participants are invented.
    const subjects: SubjectRef[] = [{ scope: 'case', id: input.caseSnapshot.caseId }];
    for (const assertion of historical) if (assertion.reviewStatus !== 'rejected' && validateAssertions([assertion], input.messages, input.factSchema).ok && !subjects.some(s => s.scope === assertion.subjectRef.scope && s.id === assertion.subjectRef.id)) subjects.push(assertion.subjectRef);
    const snapshot = { caseId: input.caseSnapshot.caseId, messages: input.messages, factSchema: input.factSchema, agentProfile: input.agentProfile, knownSubjects: subjects, historicalAssertions: historical, historicalBlockers: input.caseSnapshot.blockers, materialFieldIds: RECONCILIATION_PROFILE.fields.filter(id => input.factSchema.fields.some(f => f.id === id)) };
    try {
      const { result, trace } = await runPipeline({ runId: randomUUID(), snapshot, transport: this.transport, instructionVersion: PROMPT_VERSION });
      if (result.status === 'human_review_required') return failure('MODEL_OUTPUT_INVALID', 'La interpretación requiere revisión humana');
      if (result.status === 'failed') {
        const provider = trace.operations.some(o => ['error', 'timeout', 'cancelled'].includes(o.status));
        return failure(provider ? 'MODEL_UNAVAILABLE' : 'MODEL_OUTPUT_INVALID', provider ? 'No se pudo completar la interpretación' : 'La interpretación no superó la validación', provider);
      }
      return validateInterpretation(result.interpretation, input);
    } catch { return failure('MODEL_UNAVAILABLE', 'No se pudo completar la interpretación', true); }
  }
}
import OpenAI from 'openai';
import { zodTextFormat } from 'openai/helpers/zod';
import { normalizeWire, wireSchema } from './wire';
import { prompts } from './prompts';
import type { FakeTransport, Request } from './scheduler';
import type { Role } from './trace';

type Target = Exclude<Role, 'Repair'>;
type SDK = { responses: { create: (body: never, options: { signal: AbortSignal }) => Promise<{ status: string; output: { type: string; content?: { type: string }[] }[]; output_text: string }> } };
function target(request: Request): Target {
  if (request.role !== 'Repair') return request.role;
  const role = (request.input as { targetRole?: Role }).targetRole;
  if (!role || role === 'Repair') throw new Error('invalid target');
  return role;
}
// Strip review votes and extractor attribution from J. Equivalent alternatives
// are collapsed before presentation; candidate IDs remain valid for reconciliation.
function modelInput(role: Target, input: unknown): unknown {
  if (role !== 'J') return input;
  const data = input as { snapshot: unknown; dispute: { candidateIds: string[] }; group?: { candidates: Record<string, unknown>[] } };
  const seen = new Set<string>();
  const alternatives = (data.group?.candidates ?? []).flatMap(c => {
    const { extractorId: ignored, candidateId, ...rest } = c; void ignored;
    const key = JSON.stringify(rest);
    if (seen.has(key)) return [];
    seen.add(key); return [{ candidateId, ...rest }];
  });
  return { snapshot: data.snapshot, dispute: { ...data.dispute, candidateIds: alternatives.map(a => a.candidateId) }, alternatives };
}
export function openAIMultipassTransport(apiKey: string, model: string, client?: SDK): FakeTransport {
  const sdk = client ?? new OpenAI({ apiKey, timeout: 25000, maxRetries: 0 }) as unknown as SDK;
  return { async execute(request) {
    const role = target(request);
    const original = request.role === 'Repair' ? (request.input as { originalInput: unknown }).originalInput : request.input;
    const instructions = request.role === 'Repair' ? `${prompts.Repair}\n${prompts[role]}` : prompts[role];
    const response = await sdk.responses.create({ model, instructions, input: JSON.stringify(modelInput(role, original)), text: { format: zodTextFormat(wireSchema(role), `multipass_${role.toLowerCase()}`) } } as never, { signal: request.signal });
    if (response.status !== 'completed') throw new Error('MODEL_INCOMPLETE');
    if (response.output.some(item => item.type === 'message' && item.content?.some(c => c.type === 'refusal'))) throw new Error('MODEL_REFUSAL');
    try { return normalizeWire(role, JSON.parse(response.output_text)); } catch { return null; }
  } };
}
