      if (JSON.stringify(first) !== JSON.stringify(second)) {
        group.candidates = group.candidates.filter(c => c !== duplicate);
        rejected.push(duplicate);
        diagnostics.push({ candidateId: duplicate.candidateId, code: 'duplicate_extractor' });
